-- DVS-2225-4-03 · ce_konformitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Geräte und Maschinen müssen den Europäischen Richtlinien entsprechen. Der Hersteller oder sein in der Gemeinschaft niedergelassener Bevollmächtigter ist für die Ausstellung der EG-Konformitätserklärung und die CE-Kennzeichnung verantwortlich. — printed p.13', verification_note='md-verified 2026-09-05 (§5.1, printed p.13) [VC]', verified_at=now() where id='89a99db4-d3b9-4ac7-9e73-98e8d4414592' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-03 · parametererfassung_abstand
update public.fields set verification_status='verified_against_standard', verification_quote='Darüber hinaus müssen die Schweißmaschinen mit einer Einrichtung versehen sein, mit der die Schweißparameter zyklisch in Abständen $\leq 50 \mathrm{~cm}$ erfasst und aufgezeichnet werden. — printed p.14', verification_note='md-verified 2026-09-05 (§5.2, printed p.14) [VC]. Unit cm matches the printed unit.', verified_at=now() where id='3787ba43-0bb4-4951-bd93-7b77330c29b8' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-03 · eff_heizkeillaenge
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1. Anforderungen an die Funktionselemente. | effektive Heizkeillänge & 50 bis 100 mm & Prüfung der Funktionsfähigkeit der Maschine & $\pm 10 \%$ des angegebenen Längenwertes & Mittelwert ± 4\%, am Heizkeil für vordere und hintere Teilnaht — printed p.14', verification_note='md-verified 2026-09-05 (§5.2/Tabelle 1, printed p.14) [VC]. No gate reads this field — staged (S-5n).', verified_at=now() where id='fc307dc7-88de-498d-90bc-a3cf825e3fcb' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-03 · fuegeweg_differenz_grenze
update public.fields set verification_status='verified_against_standard', verification_quote='Das Andrucksystem muss eine gleichmäßige Verteilung der Fügekraft auf beide Teilnähte während des Schweißens soweit sichern, dass die Differenz der Fügewege der beiden Teilnähte auf maximal $0,15 \mathrm{~mm}$ beschränkt bleibt. — printed p.15', verification_note='md-verified 2026-09-05 (§5.2 Andrucksystem / Tabelle 1, printed p.14–15) [VC]. Same 0,15 mm limit is re-stated as an acceptance criterion in §6.2.12 (p.19), where gate CR-11 fails to enforce it — staged (S-5d).', verified_at=now() where id='312d8517-92d3-47fd-afd9-8b102149ece3' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-03 · warmgas_regelabweichung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Regelung der Warmgastemperatur und die Einstellung der Warmgasmenge müssen unabhängig vom Temperiersystem für das Plastifiziersystem möglich sein. Die Warmgastemperatur muss stufenlos einstellbar sein und angezeigt werden. Die Temperaturschwankung bei unveränderter Sollwerteinstellung darf $\pm 10 \mathrm{~K}$ nicht überschreiten. — printed p.15', verification_note='md-verified 2026-09-05 (§5.3 Vorwärmsystem, printed p.15) [VC]. Unit K matches. No gate reads this field — staged (S-5n).', verified_at=now() where id='a9733b08-d8eb-462c-831d-57b35f2bc15b' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-03 · masse_regelabweichung
update public.fields set verification_status='verified_against_standard', verification_quote='Das Plastifiziersystem muss in der Lage sein, das Material vollständig aufzuschmelzen und zu homogenisieren. Die Temperaturschwankung der Masse darf bei kontinuierlichem Betrieb und bei unveränderter Sollwerteinstellung $\pm 3$ K nicht überschreiten (gemessen im Zentrum der Masse) — printed p.16', verification_note='md-verified 2026-09-05 (§5.3 Plastifiziersystem, printed p.15–16) [VC]. Unit K matches. No gate reads this field — staged (S-5n).', verified_at=now() where id='b17c19b3-3cec-4d07-bb59-44452ae39f2b' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · d_N
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach Nahtform werden die in Bild 1 gezeigten Abmessungen ermittelt: | $\mathrm{d}_{\mathrm{N}}=$ Dicke der Naht (Auftragnaht) | Dicke der Naht $\left(\mathrm{d}_{\mathrm{N}}\right)$ & $1,25 \times\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)$ \\ & $1,75 \times\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)$ — printed p.19, p.6', verification_note='md-verified 2026-09-05 (§6.2.11 p.19; Bild 1 Auftragnaht p.6) [VC]', verified_at=now() where id='44596da6-46d7-465f-9938-8b242aed3cd3' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · d_N1
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach Nahtform werden die in Bild 1 gezeigten Abmessungen ermittelt: | $\mathrm{d}_{\mathrm{N} 1}=$ Dicke der vorderen Naht (Überlappnaht mit Prüfkanal) | Dicke der Naht $\left(\mathrm{d}_{\mathrm{N} 1}, \mathrm{~d}_{\mathrm{N} 2}\right)$ & $\geq\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)-0,8 \mathrm{~mm}$ \\ & $\leq\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)-0,4 \mathrm{~mm}$ — printed p.19, p.6', verification_note='md-verified 2026-09-05 (§6.2.11 p.19; Bild 1 Überlappnaht p.6) [VC]', verified_at=now() where id='3287f121-5a2c-4fc9-9ca3-503201888f71' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · d_N2
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach Nahtform werden die in Bild 1 gezeigten Abmessungen ermittelt: | $\mathrm{d}_{\mathrm{N} 2}=$ Dicke der hinteren Naht (Überlappnaht mit Prüfkanal) | Dicke der Naht $\left(\mathrm{d}_{\mathrm{N} 1}, \mathrm{~d}_{\mathrm{N} 2}\right)$ & $\geq\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)-0,8 \mathrm{~mm}$ \\ & $\leq\left(\mathrm{d}_{\mathrm{o}}+\mathrm{d}_{\mathrm{u}}\right)-0,4 \mathrm{~mm}$ — printed p.19, p.6', verification_note='md-verified 2026-09-05 (§6.2.11 p.19; Bild 1 Überlappnaht p.6) [VC]', verified_at=now() where id='f6448996-6e67-4325-b1bd-12469fb70995' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · delta_d_N1
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist nachzuweisen, dass die Nahtabmessungen den folgenden Anforderungen entsprechen: | Anhang Blatt 3: Prüfprotokoll für Überlappnähte mit Prüfkanal | & \Delta d_{N 1}=\left(d_{o}+d_{u}\right)-d_{N 1} \\ | Überlappnähte $0,40 \mathrm{~mm} \leq \Delta \mathrm{d}_{\mathrm{N} 1 / 2} \leq 0,80 \mathrm{~mm}$ — printed p.19, p.28', verification_note='md-verified 2026-09-05 (§6.2.12 p.19; Anhang Blatt 3 p.28) [VC]. Source defect noted: the §6.2.11 body prints the definition without its minus sign ("= (do + du) dN1/2"); Anhang Blatt 3 prints it correctly as (do+du) − dN1, which is what equation #1 encodes.', verified_at=now() where id='9381e70f-8377-4f46-91a4-f7a5f7945c26' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · delta_d_N2
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist nachzuweisen, dass die Nahtabmessungen den folgenden Anforderungen entsprechen: | Anhang Blatt 3: Prüfprotokoll für Überlappnähte mit Prüfkanal | & \Delta d_{N 2}=\left(d_{o}+d_{u}\right)-d_{N 2} | Überlappnähte $0,40 \mathrm{~mm} \leq \Delta \mathrm{d}_{\mathrm{N} 1 / 2} \leq 0,80 \mathrm{~mm}$ $\left|\Delta \mathrm{d}_{\mathrm{N} 1}-\Delta \mathrm{d}_{\mathrm{N} 2}\right| \leq 0,15 \mathrm{~mm}$ — printed p.19, p.28', verification_note='md-verified 2026-09-05 (§6.2.12 p.19; Anhang Blatt 3 p.28) [VC]. The printed |Δd_N1 − Δd_N2| ≤ 0,15 mm limit is NOT enforced — gate CR-11 is a presence-only no-op; fix staged (S-5d).', verified_at=now() where id='d12959e0-e916-46c8-9eff-2e8f6902a95a' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · f_NA
update public.fields set verification_status='verified_against_standard', verification_quote='& =\text { Nahtdickenfaktor für die Auftragnaht } \\ \mathrm{f}_{\mathrm{NA}} & =\mathrm{dN} /(\mathrm{do}+\mathrm{du}) | Auftragnähte $1,25 \leq f_{N A} \leq 1,75$ — printed p.19', verification_note='md-verified 2026-09-05 (§6.2.11/§6.2.12, printed p.19) [VC]. Dimensionless ("-") matches: the factor is dN/(do+du). Anhang Blatt 4 (p.29) repeats the formula.', verified_at=now() where id='d5a84aad-3471-44b0-8b3d-aa2f2152691a' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · aeussere_beschaffenheit_iO
update public.fields set verification_status='verified_against_standard', verification_quote='Die äußere Beschaffenheit der Naht ist einwandfrei, wenn sie keine Unregelmäßigkeiten und Fehlstellen aufweist. Weiter gilt: | - Bei größeren und häufig auftretenden Unregelmäßigkeiten sind die entsprechenden Nahtbereiche nachzubessern. | - Fehlstellen sind generell nachzubessern. — printed p.17', verification_note='md-verified 2026-09-05 (§6.2.5, printed p.17) [VC]', verified_at=now() where id='514f2643-bfce-48e3-ac22-a9538a960f12' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · wulst_dicke_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='- Wülste an der vorderen Kante von Überlappnähten sind nicht zulässig. Wülste in den Randbereichen von Auftragnähten sind nur zulässig, wenn sie örtlich vereinzelt auftreten. Ihre Dicke darf $50 \%$ der Dichtungsbahnendicke nicht überschreiten. — printed p.17', verification_note='md-verified 2026-09-05 (§6.2.5, printed p.17) [VC]. Unit % (of Dichtungsbahnendicke) matches. Printed hard limit with no gate — staged (S-5a).', verified_at=now() where id='7548d624-acd2-40b5-94ac-151e31eb88a6' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · kerben_tiefe_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='- Kerben und Riefen mit flachen Übergängen sind bis zu einer Tiefe von $10 \%$ der Bahndicke in begrenztem Umfang zulässig. — printed p.17', verification_note='md-verified 2026-09-05 (§6.2.5, printed p.17) [VC]. Unit % (of Bahndicke) matches. Printed limit with no gate — staged (S-5b); §7 (p.24) uses the same 10 % as the Nachbesserung trigger.', verified_at=now() where id='e2eb295d-55ec-4abb-923a-19978d4376a0' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · schaelversuch_anzahl
update public.fields set verification_status='verified_against_standard', verification_quote='Die Schälversuche sind in Anlehnung an Richtlinie DVS 2226-3 an jeweils drei etwa 20 mm breiten Streifenproben durchzuführen. — printed p.20', verification_note='md-verified 2026-09-05 (§6.3.1, printed p.19–20) [VC]. The printed count is three; the strip width (~20 mm) is not separately encoded.', verified_at=now() where id='263cb01c-b809-4d13-a3c8-c34644db9698' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · verformungsgeschwindigkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Prüfungen erfolgen mit baustellengerechten Prüfgeräten nach dem Stand der Technik, die eine zügige Lastaufbringung und eine weitgehend gleichmäßige Verformungsgeschwindigkeit von $50 \mathrm{~mm} / \mathrm{min}$ ermöglichen. — printed p.20', verification_note='md-verified 2026-09-05 (§6.3.3, printed p.20) [VC]. Unit mm/min matches.', verified_at=now() where id='2af90bc7-80f8-486c-9363-f70530da6d8c' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · restnahtbreite
update public.fields set verification_status='verified_against_standard', verification_quote='- Verstrecken des Grundmaterials, neben der Naht oder im Nahtbereich nach begrenztem Schälen der Naht. Die Naht weist noch ein ausreichendes Versagensverhalten auf, wenn die Schweißparameter bei der Herstellung der Naht und ihre Abmessungen im Toleranzbereich liegen, und - die verbleibende Restnahtbreite bei der überwiegenden Zahl der Einzelprüfungen größer ist als die geforderte Mindestbreite von 15 mm , oder — printed p.21', verification_note='md-verified 2026-09-05 (§6.3.5, printed p.21) [VC]. Unit mm matches; the 15 mm reference is the §3.1 Teilnaht minimum.', verified_at=now() where id='d4962457-6897-4e38-80d2-dae2eca04636' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · versagensverhalten
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ergebnisse dieser Prüfung dienen zur Festlegung der Schweißparameter im Rahmen der Probeschweißungen und zur Beurteilung des Versagensverhaltens von Probenahmen. Sie werden anhand folgender Kriterien beurteilt: | - Verstrecken des Grundmaterials, außerhalb der Naht, ohne Schälen der Naht. Die Naht weist ein gutes Versagensverhalten auf. | - Schälen der Naht. Die Naht weist kein ausreichendes Versagensverhalten auf. — printed p.21', verification_note='md-verified 2026-09-05 (§6.3.5, printed p.21) [VC]. The three enum values (gut / ausreichend / nicht ausreichend) are exactly the three verdicts the source prints.', verified_at=now() where id='4c1e4a05-0357-47b9-b552-e5b7b1ddec23' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · druckluft_pruefdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Der eigentliche Prüfdruck von 5 bar wird erst nach etwa einminütiger Vorbeanspruchung bei 6 bar eingestellt, um Anfangsverformungen zu konditionieren. — printed p.22', verification_note='md-verified 2026-09-05 (§6.4.2.3, printed p.22) [VC]. Unit bar matches. Caveat: the 6 bar pre-load is printed but not encoded as its own field.', verified_at=now() where id='b591b930-def4-47fb-8b85-9a05618efd04' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · druckluft_pruefzeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Prüfzeit für die Druckluftprüfung beträgt 10 Minuten. Nach Ablauf der Prüfzeit wird der Prüfkanal am Nahtende geöffnet. Der Druck (Anzeige auf dem Manometer) muss schlagartig abfallen. — printed p.22', verification_note='md-verified 2026-09-05 (§6.4.2.3, printed p.22) [VC]. Unit min matches. §6.4.2.3 also prints "Die Prüfung sollte erst etwa 1 Stunde nach dem Schweißen erfolgen." — conditioning time not encoded.', verified_at=now() where id='38249e0d-443f-4906-88b2-cec971208172' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · druckluft_druckabfall
update public.fields set verification_status='verified_against_standard', verification_quote='Die Naht gilt als dicht, wenn der Druck im Prüfkanal innerhalb der vorgegebenen Prüfdauer um nicht mehr als 0,5 bar abfällt. — printed p.22', verification_note='md-verified 2026-09-05 (§6.4.2.5, printed p.22) [VC]. Unit bar matches. Consistent with Anhang Blatt 3 (p.28), whose protocol header prints "Druckabfall: <10 %" — 10 % of the 5 bar test pressure = 0,5 bar.', verified_at=now() where id='3493b40e-29db-462d-b4af-8c16c4151fa6' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · vakuum_unterdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Die Nähte werden bei einem Unterdruck von 0,5 bar geprüft. Dieser Prüfdruck (Unterdruck) muss über einen Zeitraum von mindestens 10 s konstant gehalten werden. — printed p.23', verification_note='md-verified 2026-09-05 (§6.4.3.3, printed p.23) [VC]. Unit bar matches. No gate reads this field — staged (S-5f).', verified_at=now() where id='ab0c3565-d5c3-412b-9cf9-b8d295a02045' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · vakuum_haltezeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Nähte werden bei einem Unterdruck von 0,5 bar geprüft. Dieser Prüfdruck (Unterdruck) muss über einen Zeitraum von mindestens 10 s konstant gehalten werden. | Die Naht gilt als dicht, wenn sich der Unterdruck zügig aufbaut, über der Prüfzeit konstant bleibt und in der Naht keine Blasenbildung auftritt. — printed p.23', verification_note='md-verified 2026-09-05 (§6.4.3.3/§6.4.3.5, printed p.23) [VC]. Unit s matches. No gate reads this field — staged (S-5f).', verified_at=now() where id='f5ab6b87-c576-4666-bc6a-87b39f413e0f' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · hochspannung_pruefspannung
update public.fields set verification_status='verified_against_standard', verification_quote='Für Dichtungsbahnen ab einer Dicke von $2,5 \mathrm{~mm}$ liegt die zulässige Prüfspannung bei etwa 60 kV . Bei einer Prüfspannung von 60 kV ergibt sich in trockener Luft eine Schlagweite von etwa 20 mm . | Die Stabelektrode wird mit einer Geschwindigkeit von etwa $10 \mathrm{~m} / \mathrm{min}$ über die Naht geführt. — printed p.23', verification_note='md-verified 2026-09-05 (§6.4.4.3, printed p.23) [VC]. Unit kV matches. The value is printed as an approximation ("etwa 60 kV") that must be matched to sheet thickness and seam width — SR-2 selection, not a fixed set point. No gate reads this field — staged (S-5f).', verified_at=now() where id='469b0e79-2153-42b7-8c71-1204a6857c75' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-04 · dichtigkeit_iO
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der durchgehenden Prüfung der Nähte auf Dichtigkeit ist das Prüfverfahren auf die jeweilige Nahtform abzustimmen. Es sind folgende Prüfverfahren anzuwenden: | Die Naht gilt als dicht, wenn der Druck im Prüfkanal innerhalb der vorgegebenen Prüfdauer um nicht mehr als 0,5 bar abfällt. | Die Naht gilt als dicht, wenn sich der Unterdruck zügig aufbaut, über der Prüfzeit konstant bleibt und in der Naht keine Blasenbildung auftritt. | Die Naht gilt als dicht, wenn keine Funkenentladung auftritt. — printed p.21, p.22, p.23, p.24', verification_note='md-verified 2026-09-05 (§6.4.1 p.21; §6.4.2.5 p.22; §6.4.3.5 p.23; §6.4.4.5 p.24) [VC]. Gate CR-16 currently carries the §6.1 property-list bullet as its source_quote — retag staged (S-4d).', verified_at=now() where id='b7695b48-22b8-491b-a029-8e7951fd72b2' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-05 · schweissprotokoll_vollstaendig
update public.fields set verification_status='verified_against_standard', verification_quote='Die Schweißparameter und die Umgebungsbedingungen sind in Schweißprotokollen festzuhalten. Mit diesen Protokollen muss eine Zuordnung zum Schweißer, zu den Schweißmaschinen und -geräten (Typ und Kennzeichnung) und zur Naht sichergestellt sein. Sie sind durch die Fremdüberwachung fachtechnisch und auf Vollständigkeit zu prüfen und gegenzuzeichnen. Die Blätter 1 und 2 im Anhang zeigen Muster für Schweißprotokolle. — printed p.11', verification_note='md-verified 2026-09-05 (§4.3.1, printed p.11; Anhang Blatt 1 p.26, Blatt 2 p.27) [VC]', verified_at=now() where id='3d6a71fd-9e94-4d88-a8f6-f824e2f5bc47' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-05 · pruefprotokoll_vollstaendig
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ergebnisse der Baustellenprüfungen sind in Prüfprotokollen festzuhalten. Im Anhang sind für die verschiedenen Nahtformen Prüfprotokolle gezeigt: | Prüfprotokoll für Überlappnähte mit Prüfkanal - Anhang Blatt 3 | Prüfprotokoll für die Auftragnähte - Anhang Blatt 5 — printed p.24', verification_note='md-verified 2026-09-05 (§6.5, printed p.24) [VC]. Source defect: §6.5 points the Auftragnaht protocol at "Anhang Blatt 5", but the guideline has only four Blätter and the Inhalt (p.2) lists "Blatt 4: Prüfprotokoll für Auftragnähte" — the encoded "Anhang Blatt 3–4" follows the Inhalt and the actual annex.', verified_at=now() where id='abb70a71-d499-4b6b-b155-86e34c295019' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-05 · fremdpruefung_gegengezeichnet
update public.fields set verification_status='verified_against_standard', verification_quote='Alle Baustellenprüfungen sind im Rahmen der Eigenkontrolle durch den Verleger durchzuführen. Die Ergebnisse sind vollständig und prüfbar zu dokumentieren. | Diese Protokolle sind im Rahmen der Eigenüberwachung durch den Verleger zu führen, durch die Fremdprüfung auf Vollständigkeit und fachtechnisch zu prüfen und gegenzuzeichnen. — printed p.16, p.24', verification_note='md-verified 2026-09-05 (§6.1 p.16; §6.5 p.24) [VC]', verified_at=now() where id='b176f0e7-dd0e-412a-8f92-ff1481eec9af' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-05 · nachbesserung_zuschnitt_ueberstand
update public.fields set verification_status='verified_against_standard', verification_quote='Bei größeren Fehlerbereichen im Nahtbereich und durchgehenden Fehlstellen (Löchern) in den Dichtungsbahnen sind Dichtungsbahnenstücke oder -streifen aufzubringen. Diese Dichtungsbahnenzuschnitte müssen mindestens 10 cm über die jeweiligen Fehlerbereiche hinausgehen und sind mit Warmgasextrusionsschweißen (Auftragnaht) über dem Fehlstellenbereich aufzubringen. — printed p.24', verification_note='md-verified 2026-09-05 (§7, printed p.24) [VC]. Unit cm matches. Gate CR-18 only tests presence, not the ≥10 cm minimum — fix staged (S-5e).', verified_at=now() where id='1e319ac6-ef0a-42f3-b3b7-8958d3b667d3' and verification_status not in ('verified_against_standard','corrected');

-- DVS-2225-4-05 · nachbesserung_streifenbreite
update public.fields set verification_status='verified_against_standard', verification_quote='Durchgehend fehlerhafte Nähte und solche mit durchgehenden Unregelmäßigkeiten sind entweder zu entfernen oder auf voller Länge mit einem mindestens $0,6 \mathrm{~m}$ breiten Dichtungsbahnenstreifen abzudecken und fachgerecht zu schweißen. — printed p.25', verification_note='md-verified 2026-09-05 (§7, printed p.25) [VC]. Unit m matches. Gate CR-18 only tests presence, not the ≥0,6 m minimum — fix staged (S-5e).', verified_at=now() where id='01d212ff-37ce-40e6-b59c-056e6fe5eae1' and verification_status not in ('verified_against_standard','corrected');
